import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Img,
  staticFile,
} from "remotion";
import { Series } from "remotion";
import {
  SPRINGS,
  springIn,
  ambientDrift,
  inOutEnvelope,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

// Scene durations
const SCENE_1 = 88;   // 3.5s
const SCENE_2 = 88;   // 3.5s
const SCENE_3 = 150;  // 6s
const SCENE_4 = 175;  // 7s
const SCENE_5 = 125;  // 5s

export const durationInFrames =
  SCENE_1 + SCENE_2 + SCENE_3 + SCENE_4 + SCENE_5;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const ACCENT = COLORS.orange;

// ────────────────────────────────────────────────────────────────────────────
// Background — Back_Dark
// ────────────────────────────────────────────────────────────────────────────

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ────────────────────────────────────────────────────────────────────────────
// Reusable atoms
// ────────────────────────────────────────────────────────────────────────────

// Abstract post tile — rounded rect with subtle orange-tinted gradient
const PostTile: React.FC<{
  size: number;
  rotate: number;
  opacity: number;
  variant?: number;
  showHash?: boolean;
  showPin?: boolean;
}> = ({ size, rotate, opacity, variant = 0, showHash, showPin }) => {
  const gradients = [
    `linear-gradient(135deg, rgba(248,102,6,0.18), rgba(255,255,255,0.04))`,
    `linear-gradient(135deg, rgba(255,255,255,0.08), rgba(248,102,6,0.10))`,
    `linear-gradient(160deg, rgba(248,102,6,0.22), rgba(255,255,255,0.03))`,
    `linear-gradient(120deg, rgba(255,255,255,0.05), rgba(248,102,6,0.14))`,
  ];
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: size * 0.12,
        background: gradients[variant % gradients.length],
        border: `1px solid ${COLORS.border}`,
        opacity,
        transform: `rotate(${rotate}deg)`,
        position: "relative",
        overflow: "hidden",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      <div
        style={{
          position: "absolute",
          left: size * 0.1,
          top: size * 0.1,
          width: size * 0.55,
          height: size * 0.06,
          background: "rgba(255,255,255,0.10)",
          borderRadius: 4,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: size * 0.1,
          top: size * 0.22,
          width: size * 0.35,
          height: size * 0.045,
          background: "rgba(255,255,255,0.06)",
          borderRadius: 4,
        }}
      />
      {showHash && (
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: size * 0.45,
            fontWeight: 700,
            color: ACCENT,
            letterSpacing: "-0.05em",
            opacity: 0.85,
          }}
        >
          #
        </div>
      )}
      {showPin && (
        <svg width={size * 0.4} height={size * 0.4} viewBox="0 0 24 24">
          <path
            d="M12 2 C8 2 5 5 5 9 c0 5 7 13 7 13 s7 -8 7 -13 c0 -4 -3 -7 -7 -7 z"
            fill={ACCENT}
            opacity={0.85}
          />
          <circle cx="12" cy="9" r="2.5" fill={COLORS.bg} />
        </svg>
      )}
    </div>
  );
};

// ────────────────────────────────────────────────────────────────────────────
// SCENE 1 — Profile node + orbiting tiles
// ────────────────────────────────────────────────────────────────────────────

const SceneProfile: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const envelope = inOutEnvelope(frame, vfps, SCENE_1);
  const base = Math.min(width, height);

  const avatarIn = springIn(frame, vfps, 4, "SNAPPY");

  const cx = width * 0.62;
  const cy = height * 0.46;
  const avatarSize = base * 0.16;

  const breathe = ambientDrift(frame, 3, 90, "avatar-y");
  const breatheX = ambientDrift(frame, 2, 110, "avatar-x");

  const tiles = [
    { angle: -35, distance: avatarSize * 1.55, size: avatarSize * 0.55, delay: 14, variant: 0 },
    { angle: 45, distance: avatarSize * 1.7, size: avatarSize * 0.5, delay: 20, variant: 1 },
    { angle: 165, distance: avatarSize * 1.5, size: avatarSize * 0.48, delay: 26, variant: 2 },
  ];

  const avatarScale = interpolate(avatarIn, [0, 1], [0.4, 1]);
  const avatarBlur = interpolate(avatarIn, [0, 1], [10, 0]);

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      {tiles.map((t, i) => {
        const tIn = springIn(frame, vfps, t.delay, "ELASTIC");
        const wobble = ambientDrift(frame, 6, 140 + i * 20, `tile-${i}`);
        const orbitDrift = (frame * 0.15 + i * 30) * (Math.PI / 180);
        const a = (t.angle * Math.PI) / 180 + Math.sin(orbitDrift) * 0.05;
        const tx = cx + Math.cos(a) * t.distance + breatheX;
        const ty = cy + Math.sin(a) * t.distance + breathe + wobble;
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: tx - t.size / 2,
              top: ty - t.size / 2,
              opacity: tIn,
              transform: `scale(${interpolate(tIn, [0, 1], [0.3, 1])})`,
              filter: `blur(${interpolate(tIn, [0, 1], [6, 0])}px)`,
            }}
          >
            <PostTile
              size={t.size}
              rotate={interpolate(tIn, [0, 1], [t.angle * 0.2, 0])}
              opacity={1}
              variant={t.variant}
            />
          </div>
        );
      })}

      <div
        style={{
          position: "absolute",
          left: cx - avatarSize / 2 + breatheX,
          top: cy - avatarSize / 2 + breathe,
          width: avatarSize,
          height: avatarSize,
          borderRadius: "50%",
          background: `linear-gradient(135deg, ${COLORS.card}, ${COLORS.bg})`,
          border: `2px solid ${ACCENT}`,
          opacity: avatarIn,
          transform: `scale(${avatarScale})`,
          filter: `blur(${avatarBlur}px)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: "Inter, sans-serif",
        }}
      >
        <svg width={avatarSize * 0.55} height={avatarSize * 0.55} viewBox="0 0 24 24">
          <circle cx="12" cy="9" r="4" fill={COLORS.textMuted} opacity={0.55} />
          <path
            d="M4 21 c0 -4.5 3.5 -8 8 -8 s8 3.5 8 8"
            fill={COLORS.textMuted}
            opacity={0.55}
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

// ────────────────────────────────────────────────────────────────────────────
// SCENE 2 — Hashtag glyph with spilling post thumbnails
// ────────────────────────────────────────────────────────────────────────────

const SceneHashtag: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const envelope = inOutEnvelope(frame, vfps, SCENE_2);
  const base = Math.min(width, height);

  const hashIn = springIn(frame, vfps, 4, "SNAPPY");

  const hx = width * 0.38;
  const hy = height * 0.42;
  const hashSize = base * 0.42;

  const hashDrift = ambientDrift(frame, 3, 100, "hash");
  const hashDriftX = ambientDrift(frame, 2, 130, "hashx");

  const tiles = [
    { x: 0.62, y: 0.32, size: base * 0.08, delay: 14, variant: 0, rotate: -8 },
    { x: 0.72, y: 0.40, size: base * 0.09, delay: 18, variant: 1, rotate: 5 },
    { x: 0.66, y: 0.52, size: base * 0.07, delay: 22, variant: 2, rotate: -12 },
    { x: 0.78, y: 0.55, size: base * 0.075, delay: 26, variant: 3, rotate: 10 },
    { x: 0.58, y: 0.62, size: base * 0.065, delay: 30, variant: 0, rotate: -4 },
  ];

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      <div
        style={{
          position: "absolute",
          left: hx - hashSize / 2 + hashDriftX,
          top: hy - hashSize / 2 + hashDrift,
          width: hashSize,
          height: hashSize,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: hashIn,
          transform: `scale(${interpolate(hashIn, [0, 1], [0.5, 1])}) rotate(${interpolate(hashIn, [0, 1], [-8, 0])}deg)`,
          filter: `blur(${interpolate(hashIn, [0, 1], [8, 0])}px)`,
          fontFamily: "'GT Walsheim', Inter, sans-serif",
          fontSize: hashSize * 1.0,
          fontWeight: 800,
          color: ACCENT,
          letterSpacing: "-0.06em",
          lineHeight: 1,
        }}
      >
        #
      </div>

      {tiles.map((t, i) => {
        const tIn = springIn(frame, vfps, t.delay, "ELASTIC");
        const drift = ambientDrift(frame, 5, 90 + i * 15, `htile-${i}`);
        const driftX = ambientDrift(frame, 4, 120 + i * 10, `htilex-${i}`);
        const tx = width * t.x + driftX;
        const ty = height * t.y + drift;
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: tx - t.size / 2,
              top: ty - t.size / 2,
              opacity: tIn,
              transform: `translateY(${interpolate(tIn, [0, 1], [-30, 0])}px) scale(${interpolate(tIn, [0, 1], [0.4, 1])})`,
              filter: `blur(${interpolate(tIn, [0, 1], [5, 0])}px)`,
            }}
          >
            <PostTile size={t.size} rotate={t.rotate} opacity={1} variant={t.variant} />
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ────────────────────────────────────────────────────────────────────────────
// SCENE 3 — Hashtag branching into related hashtag network
// ────────────────────────────────────────────────────────────────────────────

const SceneRelatedHashtags: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const envelope = inOutEnvelope(frame, vfps, SCENE_3);
  const base = Math.min(width, height);

  const centerIn = springIn(frame, vfps, 4, "SNAPPY");

  const cx = width * 0.50;
  const cy = height * 0.48;
  const coreSize = base * 0.14;

  const coreDrift = ambientDrift(frame, 2, 100, "core");

  const nodes = [
    { angle: -120, distance: base * 0.28, size: base * 0.07, delay: 18, variant: 0 },
    { angle: -65, distance: base * 0.34, size: base * 0.08, delay: 22, variant: 1 },
    { angle: -10, distance: base * 0.32, size: base * 0.075, delay: 26, variant: 2 },
    { angle: 50, distance: base * 0.36, size: base * 0.085, delay: 30, variant: 3 },
    { angle: 115, distance: base * 0.30, size: base * 0.07, delay: 34, variant: 0 },
    { angle: 175, distance: base * 0.32, size: base * 0.08, delay: 38, variant: 1 },
    { angle: -90, distance: base * 0.46, size: base * 0.05, delay: 50, variant: 2 },
    { angle: -30, distance: base * 0.48, size: base * 0.055, delay: 54, variant: 3 },
    { angle: 30, distance: base * 0.46, size: base * 0.05, delay: 58, variant: 0 },
    { angle: 90, distance: base * 0.45, size: base * 0.05, delay: 62, variant: 1 },
    { angle: 150, distance: base * 0.46, size: base * 0.05, delay: 66, variant: 2 },
  ];

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      <svg
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
        }}
      >
        {nodes.map((n, i) => {
          const lineIn = springIn(frame, vfps, n.delay - 4, "LIQUID");
          const a = (n.angle * Math.PI) / 180;
          const tx = cx + Math.cos(a) * n.distance;
          const ty = cy + Math.sin(a) * n.distance;
          const drift = ambientDrift(frame, 4, 100 + i * 12, `n-${i}-y`);
          const driftX = ambientDrift(frame, 3, 120 + i * 10, `n-${i}-x`);
          const endX = tx + driftX;
          const endY = ty + drift;

          const len = Math.sqrt((endX - cx) ** 2 + (endY - cy) ** 2);
          const dashOffset = interpolate(lineIn, [0, 1], [len, 0]);

          return (
            <line
              key={`line-${i}`}
              x1={cx + coreDrift * 0.4}
              y1={cy + coreDrift}
              x2={endX}
              y2={endY}
              stroke={ACCENT}
              strokeOpacity={0.45 * lineIn}
              strokeWidth={1.5}
              strokeDasharray={len}
              strokeDashoffset={dashOffset}
              strokeLinecap="round"
            />
          );
        })}
      </svg>

      <div
        style={{
          position: "absolute",
          left: cx - coreSize / 2,
          top: cy - coreSize / 2 + coreDrift,
          width: coreSize,
          height: coreSize,
          borderRadius: "50%",
          background: COLORS.card,
          border: `2px solid ${ACCENT}`,
          opacity: centerIn,
          transform: `scale(${interpolate(centerIn, [0, 1], [0.4, 1])})`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: "'GT Walsheim', Inter, sans-serif",
          fontSize: coreSize * 0.55,
          fontWeight: 800,
          color: ACCENT,
          letterSpacing: "-0.05em",
        }}
      >
        #
      </div>

      {nodes.map((n, i) => {
        const nIn = springIn(frame, vfps, n.delay, "ELASTIC");
        const a = (n.angle * Math.PI) / 180;
        const drift = ambientDrift(frame, 4, 100 + i * 12, `n-${i}-y`);
        const driftX = ambientDrift(frame, 3, 120 + i * 10, `n-${i}-x`);
        const tx = cx + Math.cos(a) * n.distance + driftX;
        const ty = cy + Math.sin(a) * n.distance + drift;

        const isOuterRing = i >= 6;

        return (
          <div
            key={`node-${i}`}
            style={{
              position: "absolute",
              left: tx - n.size / 2,
              top: ty - n.size / 2,
              width: n.size,
              height: n.size,
              borderRadius: "50%",
              background: isOuterRing ? "rgba(255,255,255,0.04)" : COLORS.card,
              border: `1px solid ${isOuterRing ? COLORS.border : ACCENT}`,
              opacity: nIn,
              transform: `scale(${interpolate(nIn, [0, 1], [0.3, 1])})`,
              filter: `blur(${interpolate(nIn, [0, 1], [4, 0])}px)`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: n.size * 0.5,
              fontWeight: 700,
              color: isOuterRing ? COLORS.textMuted : ACCENT,
              letterSpacing: "-0.05em",
            }}
          >
            #
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ────────────────────────────────────────────────────────────────────────────
// SCENE 4 — Map pin drops with location-tagged post tiles fanning out
// ────────────────────────────────────────────────────────────────────────────

const SceneLocation: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const envelope = inOutEnvelope(frame, vfps, SCENE_4);
  const base = Math.min(width, height);

  const pinDrop = spring({
    frame,
    fps: vfps,
    delay: 6,
    config: SPRINGS.SNAPPY,
  });
  const ringIn = springIn(frame, vfps, 20, "LIQUID");

  const px = width * 0.58;
  const pyTarget = height * 0.46;
  const pinDropDistance = base * 0.30;
  const py = pyTarget - pinDropDistance * (1 - pinDrop);
  const pinScale = interpolate(pinDrop, [0, 0.6, 1], [0.5, 1.15, 1]);
  const pinSize = base * 0.13;

  const ringSize = interpolate(ringIn, [0, 1], [base * 0.05, base * 0.5]);
  const ringOpacity = interpolate(ringIn, [0, 0.3, 1], [0, 0.4, 0]);

  const tiles = [
    { angle: -150, distance: base * 0.22, size: base * 0.075, delay: 32, variant: 0, rotate: -8 },
    { angle: -100, distance: base * 0.26, size: base * 0.08, delay: 36, variant: 1, rotate: 4 },
    { angle: -50, distance: base * 0.23, size: base * 0.07, delay: 40, variant: 2, rotate: -6 },
    { angle: 30, distance: base * 0.26, size: base * 0.085, delay: 44, variant: 3, rotate: 8 },
    { angle: 90, distance: base * 0.22, size: base * 0.07, delay: 48, variant: 0, rotate: -5 },
    { angle: 150, distance: base * 0.24, size: base * 0.075, delay: 52, variant: 2, rotate: 6 },
  ];

  const pinDrift = ambientDrift(frame, 2, 100, "pin");

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      <div
        style={{
          position: "absolute",
          left: px - ringSize / 2,
          top: pyTarget + pinSize * 0.45 - ringSize / 2,
          width: ringSize,
          height: ringSize * 0.32,
          borderRadius: "50%",
          border: `2px solid ${ACCENT}`,
          opacity: ringOpacity,
          fontFamily: "Inter, sans-serif",
        }}
      />

      <div
        style={{
          position: "absolute",
          left: px - pinSize / 2,
          top: py - pinSize / 2 + pinDrift,
          width: pinSize,
          height: pinSize,
          transform: `scale(${pinScale})`,
          transformOrigin: "center bottom",
          fontFamily: "Inter, sans-serif",
        }}
      >
        <svg width="100%" height="100%" viewBox="0 0 24 24">
          <path
            d="M12 1.5 C7 1.5 3.5 5 3.5 9.5 c0 6 8.5 13 8.5 13 s8.5 -7 8.5 -13 c0 -4.5 -3.5 -8 -8.5 -8 z"
            fill={ACCENT}
          />
          <circle cx="12" cy="9.5" r="3" fill={COLORS.bg} />
        </svg>
      </div>

      {tiles.map((t, i) => {
        const tIn = springIn(frame, vfps, t.delay, "ELASTIC");
        const drift = ambientDrift(frame, 4, 90 + i * 14, `loc-${i}-y`);
        const driftX = ambientDrift(frame, 3, 110 + i * 11, `loc-${i}-x`);
        const a = (t.angle * Math.PI) / 180;
        const tx = px + Math.cos(a) * t.distance + driftX;
        const ty = pyTarget + Math.sin(a) * t.distance + drift;
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: tx - t.size / 2,
              top: ty - t.size / 2,
              opacity: tIn,
              transform: `scale(${interpolate(tIn, [0, 1], [0.3, 1])})`,
              filter: `blur(${interpolate(tIn, [0, 1], [5, 0])}px)`,
            }}
          >
            <PostTile
              size={t.size}
              rotate={t.rotate}
              opacity={1}
              variant={t.variant}
              showPin={i === 1 || i === 4}
            />
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ────────────────────────────────────────────────────────────────────────────
// SCENE 5 — Hold beat: chain visualisation, gentle drift
// ────────────────────────────────────────────────────────────────────────────

const SceneChain: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const envelope = inOutEnvelope(frame, vfps, SCENE_5);
  const base = Math.min(width, height);

  const nodes = [
    { icon: "profile", delay: 4 },
    { icon: "hash", delay: 12 },
    { icon: "network", delay: 20 },
    { icon: "pin", delay: 28 },
  ];

  const nodeSize = base * 0.10;
  const totalSpan = base * 0.66;
  const startX = width / 2 - totalSpan / 2;
  const gap = totalSpan / (nodes.length - 1);
  const cy = height * 0.50;

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      <svg
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
        }}
      >
        {nodes.slice(0, -1).map((_, i) => {
          const lineIn = springIn(frame, vfps, 6 + i * 8, "LIQUID");
          const x1 = startX + gap * i;
          const x2 = startX + gap * (i + 1);
          const dy1 = ambientDrift(frame, 3, 100 + i * 20, `chain-${i}-y1`);
          const dy2 = ambientDrift(frame, 3, 110 + i * 18, `chain-${i}-y2`);
          const len = Math.abs(x2 - x1);
          const dashOffset = interpolate(lineIn, [0, 1], [len, 0]);
          return (
            <line
              key={`chain-line-${i}`}
              x1={x1 + nodeSize * 0.5}
              y1={cy + dy1}
              x2={x2 - nodeSize * 0.5}
              y2={cy + dy2}
              stroke={ACCENT}
              strokeOpacity={0.55 * lineIn}
              strokeWidth={2}
              strokeDasharray={len}
              strokeDashoffset={dashOffset}
              strokeLinecap="round"
            />
          );
        })}
      </svg>

      {nodes.map((n, i) => {
        const nIn = springIn(frame, vfps, n.delay, "ELASTIC");
        const drift = ambientDrift(frame, 3, 100 + i * 20, `cnode-${i}-y`);
        const x = startX + gap * i;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x - nodeSize / 2,
              top: cy - nodeSize / 2 + drift,
              width: nodeSize,
              height: nodeSize,
              borderRadius: nodeSize * 0.22,
              background: COLORS.card,
              border: `1.5px solid ${ACCENT}`,
              opacity: nIn,
              transform: `scale(${interpolate(nIn, [0, 1], [0.4, 1])})`,
              filter: `blur(${interpolate(nIn, [0, 1], [4, 0])}px)`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: "Inter, sans-serif",
            }}
          >
            {n.icon === "profile" && (
              <svg width={nodeSize * 0.5} height={nodeSize * 0.5} viewBox="0 0 24 24">
                <circle cx="12" cy="9" r="4" fill={ACCENT} opacity={0.9} />
                <path d="M4 21 c0 -4.5 3.5 -8 8 -8 s8 3.5 8 8" fill={ACCENT} opacity={0.9} />
              </svg>
            )}
            {n.icon === "hash" && (
              <div
                style={{
                  fontFamily: "'GT Walsheim', Inter, sans-serif",
                  fontSize: nodeSize * 0.6,
                  fontWeight: 800,
                  color: ACCENT,
                  letterSpacing: "-0.05em",
                  lineHeight: 1,
                }}
              >
                #
              </div>
            )}
            {n.icon === "network" && (
